// logoImage.js

// Example base64 images (replace with yours)
const img1 = "data:image/png;base64,"; // red
const img2 = "data:image/png;base64,"; // blue

window.onload = function() {
  // Insert into logo-cell-1
  const cell1 = document.getElementById("logo-cell-1");
  const image1 = document.createElement("img");
  image1.src = img1;
  image1.alt = "Logo 1";
  cell1.innerHTML = "";
  cell1.appendChild(image1);

  // Insert into logo-cell-2
  const cell2 = document.getElementById("logo-cell-2");
  const image2 = document.createElement("img");
  image2.src = img2;
  image2.alt = "Logo 2";
  cell2.innerHTML = "";
  cell2.appendChild(image2);
};
